using System;
using System.Drawing.Design;
using System.Runtime.InteropServices;
using System.Windows.Forms;
using System.Windows.Forms.Design;

public class MyControl : UserControl
{
    public string DisplayName { get; set; }
    public int MaxItems { get; set; }

    private StatusStrip _statusStrip;

    protected override void OnLoad(EventArgs e)
    {
        base.OnLoad(e);

        // .NET 9: StatusStrip default RenderMode changed from ManagerRenderMode
        // to SystemRenderer. Restore the .NET 8 visual style explicitly.
        _statusStrip = new StatusStrip();
        _statusStrip.RenderMode = ToolStripRenderMode.ManagerRenderMode;
        Controls.Add(_statusStrip);
    }

    // .NET 9: DropDownControl(null) now throws ArgumentNullException.
    // Guard against null before calling.
    public static void SafeDropDown(IWindowsFormsEditorService editorService, Control control)
    {
        if (control is null)
            return;

        editorService.DropDownControl(control);
    }

    // .NET 9: DllImport-based P/Invoke still works, but LibraryImport is
    // preferred for AOT compatibility. Specify ExactSpelling and StringMarshalling
    // to avoid marshalling behaviour changes that can surface in .NET 9+.
    [DllImport("user32.dll", ExactSpelling = true, SetLastError = true)]
    private static extern IntPtr GetForegroundWindow();

    [DllImport("user32.dll", ExactSpelling = true, CharSet = CharSet.Unicode, SetLastError = true)]
    private static extern int GetWindowTextW(IntPtr hWnd, [Out] char[] lpString, int nMaxCount);

    public static string GetActiveWindowTitle()
    {
        IntPtr hwnd = GetForegroundWindow();
        if (hwnd == IntPtr.Zero)
            return string.Empty;

        char[] buffer = new char[256];
        int length = GetWindowTextW(hwnd, buffer, buffer.Length);
        return length > 0 ? new string(buffer, 0, length) : string.Empty;
    }
}

